#!/data/data/com.termux/files/usr/bin/bash
set -e
APP_DIR="$HOME/iptv-studio"

echo "=============================================="
echo " IPTV STUDIO 2026"
echo " INSTALADOR COMPLETO"
echo "=============================================="
echo ""

echo "[1/5] Actualizando Termux e instalando dependencias..."
pkg update -y
pkg install python curl -y

echo "[2/5] Creando $APP_DIR ..."
mkdir -p "$APP_DIR"

echo "[3/5] Instalando interfaz..."
echo '' | base64 -d > "$APP_DIR/IPTV_STUDIO_DULCINEA_2026.html"

echo "[4/5] Instalando servidor..."
echo '' | base64 -d > "$APP_DIR/iptv_termux_server.py"

cat > "$APP_DIR/iniciar_iptv.sh" <<'EOF'
#!/data/data/com.termux/files/usr/bin/bash
set -e
APP_DIR="$HOME/iptv-studio"
PORT=8765
cd "$APP_DIR"
if ! curl -s --max-time 2 "http://127.0.0.1:$PORT/health" >/dev/null 2>&1; then
  nohup python "$APP_DIR/iptv_termux_server.py" > "$APP_DIR/servidor.log" 2>&1 &
  sleep 1
fi
echo ""
echo "✓ IPTV STUDIO 2026 ACTIVO"
echo "✓ http://127.0.0.1:$PORT/"
command -v am >/dev/null 2>&1 && am start -a android.intent.action.VIEW -d "http://127.0.0.1:$PORT/" >/dev/null 2>&1 || true
EOF

cat > "$APP_DIR/detener_iptv.sh" <<'EOF'
#!/data/data/com.termux/files/usr/bin/bash
pkill -f "iptv_termux_server.py" 2>/dev/null || true
echo "✓ IPTV Studio detenido."
EOF

cat > "$APP_DIR/estado_iptv.sh" <<'EOF'
#!/data/data/com.termux/files/usr/bin/bash
if curl -s --max-time 2 "http://127.0.0.1:8765/health" >/dev/null 2>&1; then
  echo "✓ IPTV Studio está EJECUTÁNDOSE."
  echo "  http://127.0.0.1:8765/"
else
  echo "✗ IPTV Studio está detenido."
fi
EOF

chmod +x "$APP_DIR"/*.sh
python -m py_compile "$APP_DIR/iptv_termux_server.py"

echo "[5/5] Verificando instalación..."
curl -s --max-time 2 "http://127.0.0.1:8765/health" >/dev/null 2>&1 || true

echo ""
echo "=============================================="
echo " ✓ INSTALACIÓN COMPLETADA"
echo "=============================================="
echo ""
echo "Iniciar:"
echo "  ~/iptv-studio/iniciar_iptv.sh"
echo ""
echo "Estado:"
echo "  ~/iptv-studio/estado_iptv.sh"
echo ""
echo "Detener:"
echo "  ~/iptv-studio/detener_iptv.sh"
